     if dialer {
         report.meta_fetched += request_meta(conn, session, &their_manifest.root_tree_id)?;
         serve_meta(conn, session)?;
     } else {
         serve_meta(conn, session)?;
         report.meta_fetched += request_meta(conn, session, &their_manifest.root_tree_id)?;
