     let plan = compute_plan(session, &my.manifest, &their_manifest)?;

     // --- data phase: dialer requests first --------------------------------
     let wanted: Vec<BlobId> = plan
         .fetch
         .iter()
         .map(|(id, _)| *id)
         .filter(|id| session.store.get(BlobKind::DataChunk, id).is_err())
         .collect();
