         HoldDecision::Hold(split) => {
             report.held = split.held.len();
             HeldLedger::new(&session.state_dir).append(&peer_hex, &split.held)?;
             eprintln!(
                 "pin: held {} change(s) from peer {} (release with `ferry pin release`)",
