 /// Compare one live leaf (or bare dir kind) against the expectation.
 fn check_live_matches(
     target: &Path,
+    fold: &NfcFoldCache,
     rel: &CompPath,
     exp: &ExpectedState,
     store: &Store,
     out: &mut Vec<Divergence>,
