     )]
     WindowsDirLinkRefused { path: String },
     #[error(
         "manifest contains case-conflicting siblings under {parent}: {first:?} and \
          {second:?} cannot coexist on this filesystem; rename one of them (ferry never \
          picks silently)"
     )]
     CaseCollision {
         parent: String,
         first: String,
         second: String,
     },
+    #[error(
