 fn list_packs(store: &Store) -> Vec<String> {
     let dir = store.store_dir().join("packs");
     let mut v: Vec<String> = std::fs::read_dir(dir)
         .unwrap()
         .flatten()
         .map(|e| e.file_name().to_string_lossy().into_owned())
         .collect();
     v.sort();
     v
 }

