 fn write_file(path: &Path, bytes: &[u8], mt: (i64, u32)) {
     if let Some(p) = path.parent() {
         std::fs::create_dir_all(p).unwrap();
     }
     std::fs::write(path, bytes).unwrap();
     set_file_mtime(path, mt);
