             folder_id: FOLDER,
             device_id: self.dev,
             parent_manifest_id: self.parent,
             created_sec: self.clock,
             created_nsec: 0,
         };
         let out = snapshot_dir(&self.store, self.poly, &self.tree, &idn).unwrap();
         assert!(out.refused.is_empty());
